            starterCode: "# Library catalog system developed over time by multiple developers\n\n# Initial implementation - Basic book tracking\nbooks = [\n    {'title': 'The Great Gatsby', 'author': 'F. Scott Fitzgerald', 'year': 1925},\n    {'title': 'To Kill a Mockingbird', 'author': 'Harper Lee', 'year': 1960},\n    {'title': '1984', 'author': 'George Orwell', 'year': 1949},\n    {'title': 'Pride and Prejudice', 'author': 'Jane Austen', 'year': 1813}\n]\n\n# Addition by intern #1 - Convert to a different format\nbook_records = []\nfor book in books:\n    # Convert dictionary to list for internal processing\n    record = [book['title'], book['author'], book['year']]\n    book_records.append(record)\n\n# Addition by dev #2 - Organize by author\nauthor_books = {}\nfor record in book_records:\n    title, author, year = record\n    # Check if author exists in the dictionary\n    if author in author_books:\n        # Append the book to the existing author entry\n        author_books[author].append([title, year])\n    else:\n        # Create a new entry for the author\n        author_books[author] = [[title, year]]\n\n# Addition by dev #3 - Convert back to a more detailed format\nformatted_catalog = []\nfor author, books_by_author in author_books.items():\n    # Create entry for each author\n    author_entry = {'author': author, 'books': []}\n    # Add all books by this author\n    for book_info in books_by_author:\n        title, year = book_info\n        # Format each book with specific keys\n        book_entry = {'title': title, 'publication_year': year}\n        author_entry['books'].append(book_entry)\n    formatted_catalog.append(author_entry)\n\n# Addition by dev #4 - Sort everything\n# Sort authors alphabetically\nformatted_catalog.sort(key=lambda x: x['author'])\n# Sort each author's books by year\nfor author_entry in formatted_catalog:\n    author_entry['books'].sort(key=lambda x: x['publication_year'])\n\n# Addition by dev #5 - Create a string representation for printing\ncatalog_display = []\nfor author_entry in formatted_catalog:\n    author = author_entry['author']\n    # Add author header\n    author_section = f\"Author: {author}\\n\"\n    # Add book list with formatting\n    for book in author_entry['books']:\n        author_section += f\"  - {book['title']} ({book['publication_year']})\\n\"\n    catalog_display.append(author_section)\n\n# Addition by dev #6 - Join all sections with separators\nfinal_output = \"\\n\".join(catalog_display)\n\n# Print the final catalog\nprint(\"LIBRARY CATALOG\")\nprint(\"===============\")\nprint(final_output)"
