              starterCode: "# String manipulation utility module - developed over several years\n\n# Initialize module constants - added in v1.0\nSEPARATORS = [',', ';', '|', '/']\nDEFAULT_SEPARATOR = ','\nMAX_LENGTH = 100\n\n# Basic string utilities - added in v1.0\ndef split_string(text, separator=DEFAULT_SEPARATOR):\n    \"\"\"Split a string by the given separator.\"\"\"\n    return text.split(separator)\n\n# Enhanced splitter with validation - added in v1.2\ndef advanced_split(text, separator=DEFAULT_SEPARATOR, validate=False):\n    \"\"\"Advanced string splitting with validation.\"\"\"\n    # Verify the separator is valid\n    if validate and separator not in SEPARATORS:\n        raise ValueError(f\"Invalid separator. Must be one of: {', '.join(SEPARATORS)}\")\n    \n    # Call the basic function\n    return split_string(text, separator)\n\n# String joining utility - added in v1.5\ndef join_string(parts, separator=DEFAULT_SEPARATOR):\n    \"\"\"Join string parts with the given separator.\"\"\"\n    return separator.join(parts)\n\n# Formatter with line breaks - added in v1.8 by intern\ndef format_with_breaks(text, length=MAX_LENGTH):\n    \"\"\"Format text with line breaks at specified length.\"\"\"\n    result = \"\"\n    current_pos = 0\n    while current_pos < len(text):\n        if current_pos + length <= len(text):\n            result += text[current_pos:current_pos + length] + \"\\n\"\n        else:\n            result += text[current_pos:]\n        current_pos += length\n    return result\n\n# Advanced formatter with word boundaries - added in v2.0 by senior dev\ndef smart_format(text, length=MAX_LENGTH):\n    \"\"\"Format text with line breaks at word boundaries.\"\"\"\n    if len(text) <= length:\n        return text\n    \n    words = text.split()\n    lines = []\n    current_line = []\n    current_length = 0\n    \n    for word in words:\n        # If adding this word exceeds the length limit\n        if current_length + len(word) + (1 if current_length > 0 else 0) > length:\n            # Save the current line and start a new one\n            lines.append(' '.join(current_line))\n            current_line = [word]\n            current_length = len(word)\n        else:\n            # Add the word to the current line\n            current_line.append(word)\n            # Add word length plus a space (if not the first word)\n            current_length += len(word) + (1 if current_length > 0 else 0)\n    \n    # Add the last line if there's anything left\n    if current_line:\n        lines.append(' '.join(current_line))\n    \n    # Join lines with newlines\n    return '\\n'.join(lines)\n\n# Simplified interface added in v2.2 after team meeting\ndef format_text(text, separator=DEFAULT_SEPARATOR, break_at=MAX_LENGTH, smart_breaks=True, validate=False):\n    \"\"\"All-in-one text formatting function added for convenience.\"\"\"\n    # First split the text if a separator is specified\n    if separator:\n        parts = advanced_split(text, separator, validate)\n        formatted_parts = []\n        for part in parts:\n            # Format each part with line breaks\n            if smart_breaks:\n                formatted_parts.append(smart_format(part, break_at))\n            else:\n                formatted_parts.append(format_with_breaks(part, break_at))\n        return '\\n'.join(formatted_parts)\n    \n    # If no splitting needed, just format with breaks\n    if smart_breaks:\n        return smart_format(text, break_at)\n    else:\n        return format_with_breaks(text, break_at)\n\n# Test the utilities\ndef test_string_utilities():\n    # Test data\n    csv_data = \"apple,orange,banana,grape,kiwi\"\n    paragraph = \"The quick brown fox jumps over the lazy dog. It was the best of times, it was the worst of times. To be or not to be, that is the question.\"\n    \n    print(\"Basic Split:\")\n    print(split_string(csv_data))\n    print()\n    \n    print(\"Advanced Split with Validation:\")\n    try:\n        print(advanced_split(csv_data, ',', True))\n        # This should raise an error\n        print(advanced_split(csv_data, ':', True))\n    except ValueError as e:\n        print(f\"Error: {e}\")\n    print()\n    \n    print(\"Joining Strings:\")\n    parts = split_string(csv_data)\n    print(join_string(parts, ' | '))\n    print()\n    \n    print(\"Basic Formatting:\")\n    print(format_with_breaks(paragraph, 30))\n    print()\n    \n    print(\"Smart Formatting:\")\n    print(smart_format(paragraph, 30))\n    print()\n    \n    print(\"All-in-one Text Formatting:\")\n    print(format_text(csv_data, separator=',', break_at=10, smart_breaks=False))\n    print()\n    print(format_text(paragraph, separator=None, break_at=40, smart_breaks=True))\n\n# Run the test\ntest_string_utilities()"
