              starterCode: "# DATA ARCHIVING SYSTEM v2.3\n# Used across the company for document management\n# DO NOT change the core functionality or API\n\nimport os\nimport struct\nimport zlib\nfrom datetime import datetime\n\n# Constants and configuration - DO NOT MODIFY\nMAGIC_HEADER = b'ARCHIVE'\nFORMAT_VERSION = 1\nMETADATA_FORMAT = '>8sIII'  # Magic, version, timestamp, checksum\nRETAIN_ORIGINAL = True  # Keep original files after archiving\n\n# This marker is required by downstream systems - DO NOT MODIFY\ndef get_file_marker():\n    \"\"\"Generate a marker used by other systems to identify file boundaries.\"\"\"\n    return b'%%SECTION%%'\n\n# Archive a file with metadata - DO NOT MODIFY THE FUNCTION SIGNATURE\ndef archive_file(source_path, archive_path, compress=True):\n    \"\"\"Archive a file with metadata header.\n    \n    Args:\n        source_path: Path to the source file to archive\n        archive_path: Destination path for the archive file\n        compress: Whether to compress the data (default: True)\n    \n    Returns:\n        tuple: (success, message)\n    \"\"\"\n    try:\n        # Check if source file exists\n        if not os.path.isfile(source_path):\n            return False, f\"Source file not found: {source_path}\"\n        \n        # ERROR: The file reading has issues with binary data\n        # Read the source file\n        with open(source_path, 'r') as source_file:\n            file_data = source_file.read()\n        \n        # Compress if requested\n        if compress:\n            # Convert to bytes if it's not already\n            if isinstance(file_data, str):\n                file_data = file_data.encode('utf-8')\n            compressed_data = zlib.compress(file_data)\n            data_to_write = compressed_data\n        else:\n            # Convert to bytes if it's not already\n            if isinstance(file_data, str):\n                data_to_write = file_data.encode('utf-8')\n            else:\n                data_to_write = file_data\n        \n        # Generate metadata\n        timestamp = int(datetime.now().timestamp())\n        checksum = zlib.crc32(data_to_write)\n        \n        # Pack the metadata header\n        header = struct.pack(METADATA_FORMAT, MAGIC_HEADER, FORMAT_VERSION, timestamp, checksum)\n        \n        # Write the archive file\n        with open(archive_path, 'wb') as archive_file:\n            # Write the header\n            archive_file.write(header)\n            # Add the file marker required by other systems\n            archive_file.write(get_file_marker())\n            # Write the data\n            archive_file.write(data_to_write)\n        \n        return True, f\"Successfully archived {source_path} to {archive_path}\"\n    \n    except Exception as e:\n        return False, f\"Error archiving file: {e}\"\n\n# Extract a file from an archive - DO NOT MODIFY THE FUNCTION SIGNATURE\ndef extract_file(archive_path, output_path, decompress=True):\n    \"\"\"Extract a file from an archive.\n    \n    Args:\n        archive_path: Path to the archive file\n        output_path: Destination path for the extracted file\n        decompress: Whether to decompress the data (default: True)\n    \n    Returns:\n        tuple: (success, message)\n    \"\"\"\n    try:\n        # Check if archive file exists\n        if not os.path.isfile(archive_path):\n            return False, f\"Archive file not found: {archive_path}\"\n        \n        # Read the archive file\n        with open(archive_path, 'rb') as archive_file:\n            # Read and unpack the header\n            header_data = archive_file.read(struct.calcsize(METADATA_FORMAT))\n            magic, version, timestamp, stored_checksum = struct.unpack(METADATA_FORMAT, header_data)\n            \n            # Verify the magic header\n            if magic != MAGIC_HEADER:\n                return False, f\"Invalid archive format: {archive_path}\"\n            \n            # Check the version\n            if version != FORMAT_VERSION:\n                return False, f\"Unsupported archive version: {version}\"\n            \n            # Read the file marker\n            marker = archive_file.read(len(get_file_marker()))\n            if marker != get_file_marker():\n                return False, f\"Invalid file marker in archive: {archive_path}\"\n            \n            # Read the file data\n            file_data = archive_file.read()\n            \n            # Verify checksum\n            calculated_checksum = zlib.crc32(file_data)\n            if calculated_checksum != stored_checksum:\n                return False, f\"Checksum mismatch: data may be corrupted\"\n            \n            # Decompress if needed\n            if decompress:\n                try:\n                    decompressed_data = zlib.decompress(file_data)\n                except zlib.error:\n                    return False, \"Failed to decompress data: not a valid compressed format\"\n                output_data = decompressed_data\n            else:\n                output_data = file_data\n        \n        # ERROR: The file writing has issues with binary data\n        # Write the output file\n        with open(output_path, 'w') as output_file:\n            # Handle binary data conversion for writing\n            if isinstance(output_data, bytes):\n                # Try to decode as text for text-mode writing\n                try:\n                    output_file.write(output_data.decode('utf-8'))\n                except UnicodeDecodeError:\n                    return False, \"Cannot write binary data in text mode\"\n            else:\n                output_file.write(output_data)\n        \n        return True, f\"Successfully extracted {archive_path} to {output_path}\"\n    \n    except Exception as e:\n        return False, f\"Error extracting file: {e}\"\n\n# Verify archive integrity - DO NOT MODIFY THIS FUNCTION\ndef verify_archive(archive_path):\n    \"\"\"Verify the integrity of an archive file.\n    \n    Args:\n        archive_path: Path to the archive file\n    \n    Returns:\n        tuple: (is_valid, metadata)\n    \"\"\"\n    try:\n        # Check if archive file exists\n        if not os.path.isfile(archive_path):\n            return False, f\"Archive file not found: {archive_path}\"\n        \n        # Read the archive file\n        with open(archive_path, 'rb') as archive_file:\n            # Read and unpack the header\n            header_data = archive_file.read(struct.calcsize(METADATA_FORMAT))\n            magic, version, timestamp, stored_checksum = struct.unpack(METADATA_FORMAT, header_data)\n            \n            # Verify the magic header\n            if magic != MAGIC_HEADER:\n                return False, {\"error\": \"Invalid archive format\"}\n            \n            # Check the version\n            if version != FORMAT_VERSION:\n                return False, {\"error\": f\"Unsupported archive version: {version}\"}\n            \n            # Read the file marker\n            marker = archive_file.read(len(get_file_marker()))\n            if marker != get_file_marker():\n                return False, {\"error\": \"Invalid file marker in archive\"}\n            \n            # Read the file data\n            file_data = archive_file.read()\n            \n            # Verify checksum\n            calculated_checksum = zlib.crc32(file_data)\n            if calculated_checksum != stored_checksum:\n                return False, {\"error\": \"Checksum mismatch: data may be corrupted\"}\n            \n            # Return successful validation with metadata\n            created_date = datetime.fromtimestamp(timestamp)\n            metadata = {\n                \"version\": version,\n                \"created\": created_date.strftime(\"%Y-%m-%d %H:%M:%S\"),\n                \"size\": len(file_data),\n                \"compressed\": True,  # Assume compressed by default\n                \"checksum\": stored_checksum\n            }\n            \n            return True, metadata\n    \n    except Exception as e:\n        return False, {\"error\": f\"Error verifying archive: {e}\"}\n\n# Test the archiving system\ndef test_archive_system():\n    # Create a test text file\n    text_file_path = \"test_text.txt\"\n    with open(text_file_path, \"w\") as text_file:\n        text_file.write(\"This is a test text file.\\nIt has multiple lines.\\nLet's see if our archiving system works.\")\n    \n    # Create a test binary file (a simple image)\n    binary_file_path = \"test_binary.dat\"\n    binary_data = bytes([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]) + bytes(range(20, 50))\n    with open(binary_file_path, \"wb\") as binary_file:\n        binary_file.write(binary_data)\n    \n    print(\"TEST ARCHIVING SYSTEM\")\n    print(\"=\" * 30)\n    \n    # Test 1: Archive and extract a text file\n    print(\"\\nTest 1: Archiving text file...\")\n    text_archive_path = \"text_archive.bin\"\n    success, message = archive_file(text_file_path, text_archive_path, compress=True)\n    print(message)\n    \n    if success:\n        is_valid, metadata = verify_archive(text_archive_path)\n        if is_valid:\n            print(f\"Archive verified successfully. Created: {metadata['created']}, Size: {metadata['size']} bytes\")\n        else:\n            print(f\"Archive verification failed: {metadata.get('error', 'Unknown error')}\")\n        \n        print(\"\\nExtracting text file...\")\n        extracted_text_path = \"extracted_text.txt\"\n        success, message = extract_file(text_archive_path, extracted_text_path)\n        print(message)\n        \n        if success:\n            print(\"Comparing original and extracted text files...\")\n            with open(text_file_path, 'r') as original, open(extracted_text_path, 'r') as extracted:\n                original_content = original.read()\n                extracted_content = extracted.read()\n                if original_content == extracted_content:\n                    print(\"Success! Files match.\")\n                else:\n                    print(\"Error! Files don't match.\")\n    \n    # Test 2: Archive and extract a binary file\n    print(\"\\nTest 2: Archiving binary file...\")\n    binary_archive_path = \"binary_archive.bin\"\n    success, message = archive_file(binary_file_path, binary_archive_path, compress=True)\n    print(message)\n    \n    if success:\n        is_valid, metadata = verify_archive(binary_archive_path)\n        if is_valid:\n            print(f\"Archive verified successfully. Created: {metadata['created']}, Size: {metadata['size']} bytes\")\n        else:\n            print(f\"Archive verification failed: {metadata.get('error', 'Unknown error')}\")\n        \n        print(\"\\nExtracting binary file...\")\n        extracted_binary_path = \"extracted_binary.dat\"\n        success, message = extract_file(binary_archive_path, extracted_binary_path)\n        print(message)\n        \n        if success:\n            print(\"Comparing original and extracted binary files...\")\n            with open(binary_file_path, 'rb') as original, open(extracted_binary_path, 'rb') as extracted:\n                original_content = original.read()\n                extracted_content = extracted.read()\n                if original_content == extracted_content:\n                    print(\"Success! Files match.\")\n                else:\n                    print(\"Error! Files don't match.\")\n        else:\n            print(\"Binary file extraction failed. Fix the binary file handling in the archiving system.\")\n\n# Run the test\ntest_archive_system()"
